questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: [A, longitude of A, h, m, B, longitude of B]; signed longitudes, east positive. The rule node (sum and difference of longitudes swapped) does not apply on entry 2 (Accra on 0 degrees): there rw = -1, a time no answer reaches, used only by its test. Source: original. */
L: [["Mombasa",40,9,30,"Kampala",33],["Nairobi",37,14,0,"Accra",0],["Kisumu",35,7,15,"Mumbai",73],["Garissa",40,16,40,"Lagos",3],["Nairobi",37,18,20,"Dakar",-17],["Lodwar",36,6,45,"Jakarta",107],["Mombasa",40,11,0,"Rio de Janeiro",-43],["Eldoret",35,20,10,"Mogadishu",45],["Dakar",-17,8,5,"Nairobi",37],["Lamu",41,13,50,"Perth",116]];
ix: 1+rand(10);
E: L[ix];
la: E[2]; lb: E[6];
tA0: 60*E[3]+E[4];
d: lb-la;
ad: abs(d);
east: is(d>0);
tB: tA0+4*d;
same: is(la*lb>0);
/* diagnostics (mod one day) */
dirw: mod(tA0-4*d,1440); f15: mod(tA0+15*d,1440); h1: mod(tA0+60*d,1440);
wdl: if la*lb=0 then 0 else (if same then abs(la)+abs(lb) else abs(abs(la)-abs(lb)));
rw: if wdl=0 then -1 else mod(tA0+4*signum(d)*wdl,1440);

feedbackvariables.text:
TT: 60*ans1+ans2;
yd: TT-tA0;
c1: is(TT=tB and ans2<60 and ans2>=0 and ans1<24);
f1: is(mod(TT,1440)=tB);
w1: is(TT=dirw);
q1: is(TT=f15);
o1: is(TT=h1);
r1: is(TT=rw);
